/* Evolvlings: English text for the era 8 path conversations (parallel to events-era8.js). */
window.EVEVENTS_EN = window.EVEVENTS_EN || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Delivery 1: the Root that speaks, Hollín, Those Who Hear, the Mushroom, the oaks and the end ==================== */

  add("aurora", {
    "e8-raices": { who: {}, nodes: {
      a: { say: ["Between the stones of the Meadow square, black roots poke up, thick as arms. They lift the paving. The neighbours walk around the edges, without stepping on them.",
                 "In the middle of the square, a boy from the Quarter has fallen asleep sitting on a root. His eyes are open. He speaks with a voice that isn't a boy's: slow, deep, smelling of wet earth.",
                 "“I'm thirsty. I'm afraid. I remember everything. I remember the first mouth that drank from me. Tell it to come back.”",
                 "His mother wakes him by shaking him. The boy cries and remembers nothing. Around them, people look at each other. The Root has slept for centuries. Now it speaks."],
           opts: ["“Since when does he speak like that?”", "“Has this happened every night since the Single Song?”", "“Why did nobody believe the dreamers?”", "Cut the roots in the square", "Leave them a bucket of water", "Suggest the Quarter keep a night watch, to look after those who sleep"] },
      cuando: { say: ["A fruit seller answers without taking her eyes off the boy.",
                      "“Since Those Who Hear went down to the Tomb and woke it. They say they did it on purpose. That the Root had a right to speak. Now it speaks through the children who fall asleep in the square.”"] },
      unico: { say: ["An old man points at the fountain. Over the water floats a small, dull star that doesn't shine. A Mute Star, one of those born with the Single Song.",
                     "“Every night we sing it the same thing, and every night it's more fed up. Look at the star: it used to be still. Now it trembles when the boy speaks.”"] },
      libre: { say: ["The fruit seller shrugs.",
                     "“Because since the windmills broke, everything that's said runs around for a day and is forgotten. The Deep folk said the Root was speaking. We thought it was another rumour. Until it spoke here, in the square, through a boy's mouth.”"] },
      cortar: { say: ["You borrow an axe. You cut the thickest root, the one lifting the fountain. A warm black sap comes out that smells of cellar.",
                      "That night, in every house in the Meadow, the sleepers scream at once. The next day, the root has come back, thicker, a little further on."] },
      agua: { say: ["You fill a bucket at the fountain and leave it beside the root. Nobody looks at you kindly. Someone mutters that this is how you feed a dog that bites.",
                    "In the morning the bucket is empty and dry, as if it had never held water. The root hasn't grown. It hasn't left either. The boy from the Quarter slept without speaking."] },
      ronda: { say: ["You talk to the Quarter's neighbours. That night they set up shifts: two awake per block, with lanterns, gently waking anyone who talks in their sleep.",
                     "Nobody cuts roots. Nobody waters them. They just look after each other. On the third day, the boy's mother joins the watch with her own lantern.",
                     "“If the Root wants to speak, let it speak. But not through our children's mouths while nobody's watching.”"] },
    } },

    "e8-fanal": { who: { fanal: "Fanal, of the Lantern Houses" }, nodes: {
      a: { say: ["On the street of the Lantern Houses, a man of about fifty hoists new lanterns up the posts, one after another. They're bigger than the usual ones. They burn with an oil that never goes out.",
                 "Fanal, of the Houses. Roots don't come up where there's light. We've tested it: not one pokes up on our street. So, more light. All night, every night.",
                 "The Quarter says it can't afford lanterns. Let them buy some. We already paid for ours."],
           opts: ["“Where does that oil that never goes out come from?”", "“Do you use the Mute Star from the fountain as a lantern?”", "Help him light the whole street", "“Put everything out for one night. Let's see what the Root does.”", "“Let the Houses light the Quarter's streets too.”"] },
      aceite: { say: ["From the Crater. The Guild bottles the sap that boils in the cracks. It burns forever.",
                      "Yes, I know. It's sap. It was always sap, if it comes to that. My family has lit the Meadow with what comes out of the ground for two hundred years. Don't tell me as if it were news."] },
      estrella: { say: ["We tried to hang it. It gives no light. It stays dull, floating, looking down. We put it back in the fountain.",
                        "My grandmother said those stars are full of promises nobody wanted to make. That they're heavy. I didn't believe her. I carried it in my arms. It's heavy."] },
      encender: { say: ["You spend the afternoon with him, hoisting lanterns. By nightfall, the street is white with light. The roots at the edge slowly retreat, toward the Quarter.",
                        "See? It works.",
                        "It works. The next day there are twice as many roots in the Quarter, where there are no lanterns."] },
      apagar: { say: ["Put them out? With the Root awake?",
                      "It's hard for him. But that night he puts out the lanterns of his own house. You sit on the step, in the dark. From the ground rises a soft sound, like someone breathing.",
                      "It doesn't come. It doesn't grow. It just breathes. I thought light scared it off. Maybe light hurts it. Maybe light reminds it of something."] },
      barrio: { say: ["Light the Quarter? With our oil?",
                      "He argues with you for a good while. Then he goes down to the square and looks at the roots coming up between the Quarter's houses, where the children who talk in their sleep are sleeping.",
                      "All right. One lantern per block, on the Quarter's side. I'll pay for it. Let nobody say the Houses only light their own street. Even though it's what we've always done."] },
    } },

    "e8-vado": { who: {}, nodes: {
      a: { say: ["One morning, as you leave the house, you see a black root crossing the Ford from side to side, under the water. It's thin, like a long finger. It touches the river and stays still.",
                 "Your creature eyes it, suspicious. Then it comes closer and sniffs it. The root doesn't move.",
                 "That night, from the house, you hear something humming softly, in the water. It isn't your creature."],
           opts: ["Listen to what it's humming", "Sing it the song you bought from the Choir", "Sing it the song you wrote for the Ford", "Sing it the first thing that comes to mind, since the Ford has no song", "Dig a ditch around the house", "Let it drink from the river"] },
      oir: { say: ["You sit on the bank, in the dark. It's a clumsy three-note tune, repeating. It sounds familiar. It takes you a while to realise: it's what people sing at the Ford. It learned it by hearing it."] },
      comprada: { say: ["You sing it the Choir's song, the one about a place where the river is crossed and people wait for each other. The root trembles in the water, as if laughing.",
                        "The next day, the root is gone. But in every house in the Meadow people woke up humming the Ford's song. The Root sang it in its sleep through every mouth. A bought song sticks everywhere, down there too."] },
      propia: { say: ["You sing it the song you wrote that afternoon, the one that sounds bad. Your creature sings along, worse than ever.",
                      "The root stays still, listening. It doesn't repeat it. It doesn't understand it. At dawn, it slowly withdraws toward the depths.",
                      "A song that doesn't stick is a song the Root can't take away. That stays with you all day."] },
      sin: { say: ["You sing it the first thing that comes out. It's some nonsense about your creature and a fish. The root curls up a little, like a cat.",
                   "The next day it comes back, and the day after. It seems to like someone singing it something different every night."] },
      zanja: { say: ["You spend the day digging a ditch around your house and fill it with stones. Your creature helps in its own way: it throws dirt everywhere.",
                     "The root doesn't cross the ditch. It stays in the river. But that night you hear it knocking on the stones, slowly, all night, like someone knocking at a door."] },
      beber: { say: ["You do nothing. The root drinks from the Ford all night. In the morning the river is a little lower, and the root a little thicker.",
                     "Your creature sits beside it, watching. From that day on it greets it every morning, like an odd neighbour."] },
    } },
  });

  add("crater", {
    "e8-hervor": { who: { fumarola: "Fumarola, of the Ember Guild" }, nodes: {
      a: { say: ["In the Crater's cracks the black sap boils. It bubbles slowly, like thick soup. A woman with leather gloves up to her elbows scoops it with a ladle and pours it into jars.",
                 "Fumarola, of the Guild. Look at it: it burns on its own, no wick, and never goes out. The Lantern Houses buy everything we take out. The Guild hasn't had a year like this in five generations.",
                 "My apprentices say the cracks talk at night. That they ask us not to take any more. I don't hear anything. I have forty mouths to feed in the workshop."],
           opts: ["“What do the cracks say, exactly?”", "Buy a jar from her", "Plug the cracks with stone", "“Leave half in the cracks, so they cool on their own.”"] },
      dicen: { say: ["That it hurts. That they're thirsty. The same thing the Meadow children say when they fall asleep in the square. The same thing everyone says this year.",
                     "If something hurts you and you give it drink anyway, whose fault is it? I say the crack's."] },
      comprar: { say: ["She gives you a warm jar. Inside, a black flame moves on its own, like a fish.",
                       "That night you leave it on the table. All night the flame leans toward the floor, downward, toward the Heart. Your creature won't go near the table."] },
      tapar: { say: ["You haul stones all afternoon and plug three big cracks. Fumarola watches you with her arms crossed.",
                     "Three. There are three hundred. And tomorrow my apprentices will dig around your stones. You think you plugged something. What you did was give them more work."] },
      mitad: { say: ["Half? Do you know how much half is?",
                     "She argues it out with the whole workshop. The youngest apprentices, the ones who hear the cracks talk, vote yes. The old ones, no. Fumarola decides.",
                     "Half. For a year. If in a year my forty eat less, I'll come looking for you at your house. And if the cracks go quiet, I won't thank you. I'll ask you to explain why."] },
    } },
  });

  add("forest", {
    "e8-robles": { who: { madreselva: "Madreselva, mayor of the Forest" }, nodes: {
      a: { say: ["In the Deep Forest, every oak leans the same way: toward the Heart. Like people listening to something far off. Some already touch the ground with their branches.",
                 "An older woman, her hair braided with vines, directs a group tying the trunks with thick ropes to stakes driven into the earth.",
                 "Madreselva, mayor of the Forest. If they fall, the Forest falls. If the Forest falls, the Moss Council has nothing to govern. So we tie them. One by one. We're at two hundred."],
           opts: ["“What do the oaks hear?”", "Help tie the oaks", "“Let them lean. They're trees, they know what they're doing.”", "“Before tying them, let the Council listen to what they hear.”"] },
      escuchan: { say: ["The same as everyone: thirst. The oaks have the deepest roots in the Glade. They truly touch the Root. They heard it before anyone.",
                        "My grandmother said the oaks lean when someone is about to die. I say they lean when someone is about to ask for something. And it's best to be standing before it asks."] },
      atar: { say: ["You spend the day with the ropes. By nightfall, forty more oaks are tied, taut, the ropes singing when the wind blows.",
                    "Thank you. We'll carry on tomorrow.",
                    "That night, one rope snaps on its own. The oak doesn't fall. It leans a little further, slowly, like someone letting go of a hand."] },
      dejar: { say: ["Know what they're doing? Trees don't know anything. They grow toward where there's something. That's not knowing.",
                     "But she sends her people to rest. That night, without ropes, the oaks lean a little more. At dawn, a new path has opened between them: they all point the same way, toward the Heart."] },
      oir: { say: ["Listen to the oaks? In the Council? They'll think I've gone mad.",
                   "She does it anyway. That night, the whole Moss Council lies down on the Forest floor, ears against the earth, between the roots.",
                   "At dawn they get up silent. Nobody says what they heard. But that morning, Madreselva has ten oaks untied, the oldest ones, and lets them lean.",
                   "It isn't asking. Not yet. But it's going to ask for something of the Forest. I know it. And I want the Council standing when it does."] },
    } },

    "e8-zona": { who: { madreselva: "Madreselva, mayor of the Forest", raiz: "The Root, through the dreamers' mouths" }, nodes: {
      a: { say: ["In the deepest clearing of the Forest, the mayor stands waiting with the Council behind her. In front of them, sitting against a leaning oak, a dreamer from the Deep sleeps with open eyes.",
                 "They squeezed me. For a thousand years they squeezed me. On top of me they built, dug, sang, promised. I want a place. One. Where nobody treads. Where I can drink without being drained.",
                 "Madreselva, mayor of the Forest. It's asking for the Forest. I knew it. But something else can be given. The Hollow, for instance. There's sap there already. The shadows live there. Nobody wants it."],
           opts: ["“Is the Hollow yours to give?”", "“What happens to the zone we give it?”", "Give the Deep Forest to the Root", "Give the Hollow, as Madreselva proposes", "Refuse: no zone"] },
      suya: { say: ["No. It's not mine. That's why it's easy to give.",
                    "She says it without lowering her eyes. Behind her, someone on the Council looks at their hands.",
                    "Being mayor is that: bargaining with what you have, and when it's not enough, with what others have. Don't reproach me if you won't offer something else."] },
      pasa: { say: ["I stay. Forever. Nobody comes in, nobody goes out. Whatever grows there, grows for me.",
                    "A closed zone. Forever. For the generations to come. And in exchange, it stops asking in the others. That's what it says. That's also what it said the last time someone promised it something."] },
      bosque: { say: ["Madreselva stands still for a long time. Then she nods, just once.",
                      "That week, the Moss Council leaves the Forest with what it can carry. The oaks lean all the way, until they touch the ground, and the earth closes over the paths.",
                      "I gave it the only thing that was mine. Now I govern nothing. I should feel worse. I feel like someone who's stopped carrying something very heavy."] },
      hondonada: { say: ["The dreamer nods in her sleep. That night, the black sap rises knee-deep in the Hollow. The shadows living there come out with what they can carry, in a line, toward nowhere.",
                         "There. The Forest stays standing. The Council stays standing.",
                         "She doesn't look at you as she says it. The next day, the Forest is full of homeless shadows asking for somewhere to sleep. Madreselva gives them a place. Nobody thanked her."] },
      negar: { say: ["None. None. Always none.",
                     "The dreamer wakes with a start, crying. The oaks creak all at once, and at the far end of the Forest the first one falls, roots and all.",
                     "Well. Now we know what it costs to tell it no. One at a time. It'll keep asking, and we'll keep tying."] },
    } },
  });

  add("heights", {
    "e8-paso": { who: { brisa: "Brisa, the Choir's old voice" }, nodes: {
      a: { say: ["On the highest pass of the summit, where the wind rises from the depths, an old woman with faded colored ribbons in her hair sits on a stone. Her eyes are closed. She's listening.",
                 "Brisa. I was the Choir's voice, long ago. Now I'm an old woman who listens to the wind. And the wind doesn't bring songs anymore. It brings a voice. It asks for water on every pass, in the same voice.",
                 "The shepherds say it's the Root. I say it's the Root singing the only song it knows. We sang to it so much that it learned."],
           opts: ["“What happened to the windmills?”", "“You broke the windmills with me.”", "“You sang in all twelve windmills at once.”", "Ask her to sing against the wind, like before", "Listen to what the voice says", "“Let the Heights answer it. One single answer, from the whole summit.”"] },
      molinos: { say: ["Some are still there, old. The wind took others. Nobody sings inside anymore. No need. The Root sings on its own, and nobody can sell it to anyone.",
                       "All that fighting to own the song of the moment. The song of the moment now is a thirst."] },
      libre: { say: ["I remember. I took the axe first. I said what a relief. It was a relief, for a few years. Then the fear came, as I also said.",
                     "Nobody believed me when I said the voice in the wind was the Root's. They no longer believed anyone who sang. Not even me."] },
      unico: { say: ["I remember. I chose the song, in the end. Slow, simple. We sang it that every night, thirty years. Now the wind gives it back to me, twisted, in its voice.",
                     "It's like hearing a child repeat what you shouted at it. You regret everything you shouted."] },
      cantar: { say: ["Brisa stands, slowly. She opens her mouth and sings, facing the wind. Her voice is worn, cracked. It still gets into your bones.",
                      "For a while, on that pass, the wind carries her song and not the voice from below. Then she runs out of breath. She sits. The Root's voice returns.",
                      "It used to last longer. It used to be worth more. Still, for a while, I covered it. Thank you for asking me."] },
      escuchar: { say: ["You sit beside her and close your eyes. The wind rises warm from the depths. At first it's only noise. Then it becomes words.",
                        "“Water. A place. The first one. Give me back the first one. The one that drank and flew off toward the light.”",
                        "Did you hear it? It's talking about someone. Always about someone. Like a mother calling a child from the window."] },
      contestar: { say: ["Answer it? With what? With a song? I don't have a Choir anymore.",
                         "Not with a song, you tell her: with an answer. Brisa thinks it over. That week, the five villages of the Heights gather at the pass. They argue for three days over what to tell the Root.",
                         "In the end, all together, they shout one single sentence toward the depths: “We hear you. We have no water to give you. We have a place at the table.” The wind stays still for a long moment.",
                         "I don't know if it understood. But it's the first time in my life the summit has said something without selling it."] },
    } },

    "e8-tarara": { who: { tarara: "Tarará, of the Meadow" }, nodes: {
      a: { say: ["At the old lookout on the summit, a woman in her thirties sits on the edge, legs dangling over the drop. Her lips move without a sound.",
                 "Tarará, of the Meadow. You knew me as a girl, I think. When I couldn't stop singing. You came to my house. My mother still remembers.",
                 "Now I hear the voice. The one from below. Clearer than anyone, Those Who Hear say. They want me to go to the temple and speak for it."],
           opts: ["“Do you still sing with your hands?”", "“Do you remember any song?”", "“Do you still sing in your sleep?”", "“What does the voice say?”", "“Go to the temple. Let someone who truly hears it speak for it.”", "“Don't go. You don't owe your mouth to anyone.”"] },
      manos: { say: ["(She moves her hands, fluently) Every day. Inside I still hear everything. Outside, silence. Arpegia taught me, before she died. Now I teach the children who hear too much.",
                     "The Root doesn't hear hands. That's why I can talk about it without it finding out."] },
      callada: { say: ["None. Not even the lullaby. My mother sang it to me all my life and it never stuck. The shadow of forgetting left me clean.",
                       "That's why the voice from below comes in so clearly. There's nothing inside to cover it. I'm an empty room where it speaks."] },
      canta: { say: ["Every night. Now I sing what's below. My neighbours say the Root learned the songs from me, that I sang them to it in my sleep for thirty years.",
                     "Could be. I sang it everything the Glade forgot. Now it remembers. I don't."] },
      voz: { say: ["That it's thirsty. That it's afraid they'll put it back to sleep with a song. That the first one who drank owes it something. And something else, that Those Who Hear don't repeat.",
                   "That it's tired of people speaking for it. That it wants its own mouth. They don't say that in the temple."] },
      templo: { say: ["Speak for it? All day?",
                      "She looks at the drop for a long while. Then she stands up.",
                      "All right. Someone will speak it anyway. Better someone who also says what isn't convenient. The part about its own mouth. I'll say that."] },
      no: { say: ["I don't owe my mouth to anyone. You say it as if it were easy.",
                  "She stays at the lookout. That night, the voice from below seeks her out, louder than ever. Tarará covers her ears with her hands and sings something of her own, out of tune, until she falls asleep.",
                  "Next time you come, sing me something yourself. So I have one more voice, in case mine isn't enough."] },
    } },
  });

  add("hollow", {
    "e8-niscalo": { who: { niscalo: "Níscalo, of the House of the Mushroom", fosca: "Fosca, of the Veiled Court" }, nodes: {
      a: { say: ["In the Hollow, someone has opened long ditches in the ground. Black sap runs through them, slowly. On both sides grow black mushrooms that glow at night, like embers.",
                 "Níscalo, of the House of the Mushroom. My grandfather Moho sang to the mushrooms. I don't sing: I dig. The sap is coming back, and where there's sap there are mushrooms. Mushrooms cure fevers, bad dreams, the Deep cough. For the first time, nobody in the Mushroom goes hungry.",
                 "At the edge of the ditch, a tall shadow, thin as smoke, watches him with arms crossed.",
                 "Fosca, of the Veiled Court. These ditches run through where we sleep. The sap soaks us. And the glowing mushrooms won't let us hide. They took our night away."],
           opts: ["“Did your family dig the ice, long ago?”", "“Why was the Mushroom always left behind?”", "Help Níscalo dig another ditch", "Fill in the ditch that runs where the shadows sleep", "“Let the Mushroom share its mushrooms with the Court. And dig far from where they sleep.”"] },
      esporina: { say: ["My great-great-grandmother Esporina. We have her shovel hanging in the house. She dug in the Deep's ice to cure thirty sick people, and the Root turned over in its sleep.",
                        "Every time the Mushroom digs, something moves below. We know it. We dig anyway. Nobody else cures what we cure."] },
      atras: { say: ["Because we grow where nobody wants to live. In ice, in shadow, in rot. When the Glade is healthy, the mushrooms die and we with them.",
                     "When the Glade is sick, they come looking for us. Nobody wants us near when things are well. Do you understand what that is? To benefit when others are unwell."] },
      cavar: { say: ["You dig with him until noon. The sap flows into the new ditch, warm, and within an hour the first mushrooms are showing.",
                     "This is worth a week of food for my house. Take your share.",
                     "Fosca says nothing. She leaves with the other shadows, further off, toward the edge of the Hollow, where there's still darkness."] },
      tapar: { say: ["You fill the ditch with earth and stones. The sap turns aside. The mushrooms along the edge go out, one by one.",
                     "There was medicine there for twenty houses. Twenty. Are you going to bring them another?",
                     "Thank you. Tonight we sleep. Tomorrow he'll dig another, a little further on. That's how it is with the Mushroom."] },
      compartir: { say: ["Share? With them? They never bought a single mushroom.",
                         "Nobody ever sold us one.",
                         "They look at each other for a long while. In the end, Níscalo closes the ditch that runs where the shadows sleep and opens another, longer one, on the other side. He gives Fosca a basket of mushrooms.",
                         "The ones that cure bad dreams. We'll use them. Since the Root started speaking, we shadows dream of it.",
                         "Let nobody say the Mushroom only shares when it has extra. Even though that's what I'm doing."] },
    } },

    "e8-setas": { who: { niscalo: "Níscalo, of the House of the Mushroom" }, nodes: {
      a: { say: ["A man of the House of the Mushroom, his nails black with earth, takes you to the Mushroom's great fields, at the far end of the Hollow. Miles of black mushrooms on sap, glowing under a starless sky. It smells of cellar and of bread.",
                 "Níscalo, of the Mushroom. This feeds the whole House. It cures half the Glade. And every mushroom we cut, the Root feels. It wakes a little more. It drinks a little more from the rivers, to make up for it.",
                 "Those Who Hear say an awake Root is good for us. The Meadow folk say we're the ones waking it. Both are true. What do I do with my fields?"],
           opts: ["“What happens if the Root falls asleep again?”", "Let the Mushroom harvest", "Burn the mushroom fields", "“Harvest only the mushrooms that heal. Leave the others.”"] },
      duerme: { say: ["The mushrooms die. All of them. Like in my great-great-grandmother's time, when the sap cleared. The Mushroom goes back to being the one who begs.",
                      "That's why the House wants it to stay awake. Dreaming, some say. Neither asleep nor awake: dreaming. That would be best for us. I don't know if for anyone else."] },
      cosecha: { say: ["Níscalo nods. That week, the Mushroom harvests everything. The carts leave full toward the Meadow, the Crater, the Deep. For the first time, the House of the Mushroom buys land in the Meadow.",
                       "That night, every dreamer in the Glade screams at once. The Root doesn't calm. But it doesn't get angry either: it drinks. The rivers drop a finger's width.",
                       "Nobody will leave us behind again. We paid for it with something. I don't know what yet."] },
      quemar: { say: ["Níscalo looks at you as if you'd struck him. Then, in silence, he brings torches.",
                      "The fields burn all night. The black mushrooms crackle and give off a sweet smoke. The Root, below, goes still, like an animal that stops hurting.",
                      "There. Tomorrow the Mushroom has nothing. Again. If the Root falls asleep, it won't be thanks to us. It'll be because of us, as always."] },
      remedios: { say: ["Only the healing ones? That's a third. The rest are the ones that sell.",
                        "He thinks it over all night. At dawn, he has only the medicine mushrooms harvested. The others stay, glowing, with nobody touching them.",
                        "The House won't be rich. It'll be needed. My grandfather said that's worse, because they only look for you when it hurts. We'll see."] },
    } },
  });

  add("lake", {
    "e8-espejo": { who: { bajamar: "Bajamar, of the Tides" }, nodes: {
      a: { say: ["On the shore of Mirror Lake there are people kneeling, drinking from their hands, without stopping. Their bellies are swollen and they keep drinking. A woman of the Tides, wet to the waist, pulls them away from the water one by one.",
                 "Bajamar, of the Tides. The lake no longer shows what it remembers. It shows what the Root wants. And the Root wants water. Whoever looks in feels its thirst. And drinks for it.",
                 "We Tides live in the water. Now the water frightens us. I don't know what to do with that."],
           opts: ["Look into the lake", "Cover the shore with tarps so nobody looks in", "“Let the Tides carry water to the Heart. So it doesn't have to ask for it through anyone's mouth.”"] },
      mirar: { say: ["You look in. The water is still. Below, in the reflection, you aren't there: there's a river running down toward the depths of the Glade, and at the end of the river, a small light flying away.",
                     "You feel an enormous thirst, a thousand years old. Bajamar grabs your arm before you bend down.",
                     "What did you see? Don't tell me water. Everyone says water. What else?"] },
      tapar: { say: ["With Bajamar and three neighbours you cover the shore with old tarps, tied to stakes. Nobody can look in. People sit on the other side, thirsty, not knowing for what.",
                     "It works. For now. But a covered lake is a lake nobody looks after. I can already see the children lifting the corners to peek."] },
      llevar: { say: ["Carry it water? To the stump? In buckets?",
                      "In jugs. That week, the Tides organise a line: jugs of lake water, hand to hand, from the shore to the Heart. It takes a whole day.",
                      "They pour the water at the foot of the stump. The earth swallows it in a second. That night, the lake shows the sky again, for the first time in a month.",
                      "A night of peace for a day in line. It's not a good deal. But it's the first one we've made with it instead of against it."] },
    } },
  });

  add("caves", {
    "e8-eco": { who: { caliza: "Caliza, of the Hondura" }, nodes: {
      a: { say: ["In the tunnels of the Caves nobody talks. The miners communicate by knocking on the wall. A miner of the Hondura, her face white with dust, puts a finger to your lips before you say anything.",
                 "(Very quietly) Caliza, of the Hondura. Don't speak loudly. The echo doesn't repeat anymore. It answers. In its own voice, slow, from below. Yesterday a lad asked as a joke “is anyone there?”, and the echo told him his name.",
                 "Since then the lad doesn't sleep. The others don't talk. The Hondura works in silence. You can't live like that for long."],
           opts: ["Ask the echo something", "Seal the tunnel that answers", "“Let the Hondura write in the stone what the echo answers.”"] },
      preguntar: { say: ["You stand in the tunnel. Caliza moves away, covering her ears. You ask the first thing that comes to mind: “What do you want?”",
                         "The echo takes a while. Then it answers, from very far below: “To sleep. Without thirst. Without being sung to. Without being promised. To sleep because I want to, not because I'm made to.”",
                         "That's more than it's answered anyone. Why you? What does it owe you?"] },
      tapar: { say: ["With Caliza and two miners you bring stones and close the echo's tunnel. You strike the last stone with the hammer. The blow doesn't come back.",
                     "There. Now there's one tunnel fewer. The Hondura has many. The echo will find another."] },
      escribir: { say: ["Write? Like on the old walls, the ones with the drum verses?",
                        "They do it. For a week, a miner asks and Caliza carves into the stone, with a chisel, what the echo answers. Each answer, dated.",
                        "By the end of the week there's a whole wall. The Hondura folk come to read it in silence. There are things about thirst, about fear, about someone who drank first. There's a single line repeated ten times: “You don't listen to me, you use me.”",
                        "Now nobody can say it for it. It said it, and it's in the stone. Let those who come read it."] },
    } },
  });

  add("deep", {
    "e8-templo": { who: { ensuena: "Ensueña, voice of Those Who Hear" }, nodes: {
      a: { say: ["In the White Deep, over the Frozen Tomb, there's a temple of ice with walls so thin you can see the light inside. Inside, a hundred dreamers sleep at once, in rows, with a grey ribbon on their wrists.",
                 "Ensueña, voice of Those Who Hear. Welcome to the place where we finally listen to it. Seven generations sang to it to keep it quiet. We woke it so it would speak. It's one more people. The oldest.",
                 "Everything I dream comes from it. Last night I dreamed of my mother's soup. That means the Root misses something warm. Everything makes sense, if you listen."],
           opts: ["“Long ago, I wore the grey ribbon.”", "“Generations ago I handed dreamers over to the Regent.”", "“Couldn't your mother's soup just be your mother's soup?”", "Go in and listen with the dreamers", "“Let the Deep's watch in. Don't let the temple be only yours.”", "Leave the temple"] },
      cinta: { say: ["We know. It's written on the wall by the entrance: the first ones who joined. There's one without a name, it only says “the Keeper of the Ford”. I thought it was a legend.",
                     "If it was you, then you started all this. Thank you. Or sorry. I still don't know which."] },
      entrega: { say: ["Ensueña goes quiet for a while. Some dreamers, in the rows, turn over in their sleep.",
                       "Regent Albina took them out of the Deep, with your help. My great-great-grandmother was one of them. She went back to dreaming in secret, in a cellar, for forty years. I don't hold it against you. She did, until she died."] },
      sopa: { say: ["Nothing is only what it is. That's what we teach here.",
                    "She says it very surely. But she touches the ribbon on her wrist, slowly, like someone feeling for something in an empty pocket."] },
      entrar: { say: ["You lie down in a row, between two dreamers. Ensueña ties a grey ribbon on your wrist. You close your eyes.",
                      "You dream of water running down, of a moth flying away toward the light, of a thousand years of people singing above. And of the soup of a mother you don't know.",
                      "When you wake you don't know which part was the Root's and which was the woman's beside you. Ensueña smiles: she says it was all the Root's."] },
      guardia: { say: ["The watch? Those who sing the lullaby to put it to sleep? They come to silence it.",
                       "You explain: no. To watch. To look after those who sleep, like in the Meadow. That if the Root is a people, the other peoples must be able to come in and see it.",
                       "Ensueña takes a week to decide. In the end she opens the doors. The Deep's watch comes in silently, without singing, and sits among the rows.",
                       "If it's a people, let the other peoples see it. You're right. It bothers me that you're right."] },
      irte: { say: ["You'll be back. Everyone comes back. When they start dreaming of it, they come back.",
                    "You go out into the cold. That night, at home, you dream of water running down. Your creature wakes you by licking your face."] },
    } },

    "e8-sonadores": { who: { ensuena: "Ensueña, voice of Those Who Hear" }, nodes: {
      a: { say: ["Outside the temple, on the ice, a woman with a grey ribbon on her wrist hands out grey ribbons to a long line of people from every people. Folk from the Meadow, the Crater, the Heights. They all say they've dreamed of the Root.",
                 "Ensueña, voice of Those Who Hear. More come every day. They say the Root spoke to them. Some repeat things it already said. Others say new things. We write everything down. It's all its voice.",
                 "In the Meadow they say we lie. That we make up what suits us. What do you think?"],
           opts: ["“How do you know which part is the Root's?”", "Believe them", "Test whether they lie", "Dream too, to find out"] },
      como: { say: ["Because they dream things they don't know. A girl from the Crater dreamed of a lamplighter fasting in the Heart. She's never been down to the Heart.",
                    "And because if it were made up, it would be prettier. Nobody makes up a thirst like that."] },
      creer: { say: ["You tell her you believe them. Ensueña hugs you hard, suddenly, without asking.",
                     "That week, Those Who Hear go down to the Meadow with your name on their lips: the Keeper of the Ford believes us. The temple line doubles.",
                     "From today, what we dream carries weight. Thank you. Now we have to dream well. That scares me more than before."] },
      probar: { say: ["You propose a test: you'll tell the Root, in the Heart, something nobody else knows. Then you'll see whether any dreamer repeats it.",
                      "That night, in the Heart, you quietly tell the stump the name of the first creature you looked after. Three days later, two dreamers repeat it. Twenty others say something else, each one different.",
                      "Two. Two truly heard it. And twenty dreamed what they wanted to dream. Me too, maybe. I no longer know which part of me is it."] },
      sonar: { say: ["You take a grey ribbon. That night you sleep in the temple, among the dreamers, without anyone telling you what to dream.",
                     "You dream of a thousand-year thirst, of a moth, of a river. And at some point the thirst speaks to you, without words, straight to you. It recognises you.",
                     "When you wake, your mouth is dry. From that night on you dream of it now and then. Ensueña says you're now part of Those Who Hear. You don't say no."] },
    } },
  });

  add("heart", {
    "e8-hollin": { who: { hollin: "Hollín, who fasts" }, nodes: {
      a: { say: ["At the edge of the Heart's stump, a very thin man sits on the ground, covered in grey moths as if in a coat. In front of him is an old lantern, unlit, its glass black with smoke.",
                 "Hollín. My name is Hollín. You look like you've seen me before. I've seen many faces like yours. Always the same one, it seems to me: the face of whoever looks after things.",
                 "I fast. I've fasted for centuries. I thought that paid for it. Now the Root has woken and calls me by my old name, the one I had when light came out of the ground and I had wings."],
           opts: ["“What are you, Hollín?”", "“Generations ago you told me you were fasting. Still?”", "“You knew where the oil came from.”", "Sit with him, in the dark", "Light his lantern", "“It won't take you. I promise.”"] },
      que: { say: ["I was a moth. A Star, the old folk say, the kind that shines. I was the first to drink from the Root, when its sap was light and nobody knew it belonged to someone. I drank and grew big. Then I became a man, to hide among you.",
                   "Everything the Glade suffered afterwards began in my mouth. The wells, the lanterns, the wars over light. That's why I don't eat. It's little. It's what there is."] },
      ayuno: { say: ["Still. You offered me bread, that time, and I left it for the moths. These are granddaughters of granddaughters of those. They've eaten for me all this time."] },
      sabia: { say: ["I knew before anyone. I knew because I was the first to drink it. Thirty years lighting lanterns with my own guilt, and I never told anyone.",
                     "Nobody else ever asked me. Only you."] },
      oscuras: { say: ["You sit beside him. The moths brush your face. A long while passes without either of you saying anything. Below, the earth breathes.",
                       "If they hand me over, the Root calms down for a while. If not, it keeps asking. I don't know what I want. I want someone to decide for me, for the first time in a thousand years. It's cowardice. I know.",
                       "When you leave, he's already asleep, sitting up. The moths settle over him like a blanket."] },
      luz: { say: ["You bring a match to the wick. The flame catches. Hollín stares at it open-mouthed, unblinking. The moths throw themselves at the glass.",
                   "He stretches out his hand, slowly, and stops a finger's width from the light. At his feet, the stump's roots move toward the lantern too.",
                   "Leave it a while. I want to see how long I can hold out. A thousand years and I still don't know how long I can hold out."] },
      promesa: { say: ["Don't promise. Down here promises are heard. It hears them all, and remembers them all.",
                       "But he smiles, for the first time. A small, crooked smile, from someone who forgot how it's done.",
                       "Thank you anyway. Nobody has promised anything for me in a thousand years."] },
    } },

    "e8-pide": { who: { ensuena: "Ensueña, voice of Those Who Hear", hollin: "Hollín, who fasts", raiz: "The Root, through the dreamers' mouths" }, nodes: {
      a: { say: ["In the Heart, a woman with a grey ribbon on her wrist sleeps standing up in front of the stump. Her eyes are open. When she speaks, the voice isn't hers.",
                 "I'm thirsty. I'm afraid. I remember. The first one drank from me and flew away. It's here. I can smell it. Give it back to me. If you give it back, I'll sleep. If not, I'll keep asking.",
                 "Beside her, a thin man covered in moths doesn't raise his head.",
                 "It's me. Hollín. It's asking for me. It has asked for me for a thousand years, but never this clearly.",
                 "(Waking with a start, trembling) Ensueña, I'm Ensueña, of Those Who Hear. What did it say? I never remember what it says. Did it ask for something?"],
           opts: ["“What happens to Hollín if we hand him over?”", "“And if nobody hands him over?”", "Hand Hollín over", "Refuse", "Offer yourself in his place"] },
      q1: { say: ["I don't know. I go back to it. It drinks me, as I drank it. Maybe I become sap. Maybe nothing.",
                  "Those Who Hear believe it would calm down for a whole generation. Maybe two. But we believe it because we dreamed it. You know how that is."] },
      q2: { say: ["It keeps asking. Louder every night. The dreamers don't rest anymore. There are three in the temple who haven't woken for a week.",
                  "Because of me. There are three who don't wake because of me. I know. Don't tell me again."] },
      entregar: { say: ["You don't quite get to say it. Hollín stands up on his own, as if he'd been waiting. The moths rise with him.",
                        "He walks to the stump and rests his hand on the wood. He grows thin as paper. The moths come loose from him and leave, all together, upward, toward the Meadow's light.",
                        "Where he was, the unlit lantern remains. Below, deep in the Root, a small light can be seen for a moment, trembling.",
                        "It went quiet. For the first time, in my mouth, it went quiet. I don't know if it's sleeping or busy."] },
      negar: { say: ["You say no. That Hollín stays. The sleeping woman speaks again in the voice from below.",
                     "Then I keep asking. You always say no to what I ask, and yes to what you take from me.",
                     "The ground trembles. The stump's roots slowly withdraw, like an arm folding.",
                     "Thank you. I think. I don't know if thank you. Now I'll have to go on living, and knowing."] },
      ofrecer: { say: ["You put your hand on the stump. You say: take me instead. The sleeping woman turns her head toward you, slowly.",
                       "You didn't drink. But you were close. You're always close. Every time the Glade turns, you're there. I accept you a little.",
                       "You feel thirst. A thirst that isn't yours, that lodges in your throat. From that night on, now and then, you dream what the Root dreams.",
                       "(Weeping, without covering his face) Nobody offered themselves for me. In a thousand years, nobody."] },
    } },

    "e8-pacto": { who: { raiz: "The Root, through the dreamers' mouths" }, nodes: {
      a: { say: ["At the foot of the stump, an old dreamer from the Deep sleeps sitting with his back against the wood. When you arrive, he opens his eyes without waking. He speaks in the voice from below.",
                 "You. You were there last time. When they all sang to me at once. When they broke the wind. When they promised each other things in silence. You're always there.",
                 "I listened to them for a thousand years. Now I want them to listen to me. Once. Without a song. Without a promise."],
           opts: ["“What did you feel when the whole Glade sang you the same thing?”", "“What did you feel when the windmills broke?”", "“Do you know about the pacts made with hands?”", "Tell it one of the hand pacts", "Ask its forgiveness", "“We owe you nothing. You took things from us too.”"] },
      unico: { say: ["One single song. All night. Every night. Like a hand over my mouth. I slept because they left me nothing else.",
                     "And every promise they sang to me without meaning it stayed up there, floating. The Mute Stars are mine. They're what they didn't mean when they said it to me."] },
      libre: { say: ["Ownerless silence. Everyone's noise. A thousand half-things reached me, a thousand mixed dreams. None was for me. Nobody spoke to me.",
                     "That's why I spoke louder. And nobody believed me, because they no longer believed anything."] },
      manos: { say: ["I know there's something. The peoples look at each other in a way they didn't before. They keep promises they never told me. There's a pact, and I'm not in it.",
                     "For a thousand years I was the one who heard every promise. Now I'm the only one who doesn't. Do you know what that is? It's like being shut out of the house you hold up."] },
      contar: { say: ["You tell it aloud one of the pacts of the Hand Song: that the Crater rests an hour a day and the Quarter tends its ovens meanwhile.",
                      "The old dreamer goes still. Then, in the voice from below, he repeats the pact word for word, slowly, like someone learning a prayer.",
                      "Now I know. One. I'm missing the rest. But now I know it can be known."] },
      perdon: { say: ["Forgiveness? For which part?",
                      "You don't know what to answer. There are too many parts. The old dreamer smiles with a mouth that isn't his.",
                      "All right. You don't know. I wouldn't either. It's the first time someone has asked my forgiveness without asking me for something afterwards. I'll keep it."] },
      nada: { say: ["I took from you?",
                    "You tell it: the sap that sickened the Quarter, the stolen dreams, the fevers, those who never woke. The old dreamer is silent for a long time.",
                    "I don't know what I took. I only slept badly. Nobody ever told me my dreams hurt. Now I know. I don't know what to do with knowing."] },
    } },

    "e8-final": { who: { ensuena: "Ensueña, voice of Those Who Hear", niscalo: "Níscalo, of the House of the Mushroom", madreselva: "Madreselva, mayor of the Forest", raiz: "The Root, through the dreamers' mouths" }, nodes: {
      a: { say: ["The Waking Root falls, but it doesn't sleep. It stays watching, eyes open, from every crack in the Heart. In front of the stump stand the voice of Those Who Hear, the man of the Mushroom and the mayor of the Forest. Behind them, a hundred dreamers asleep on their feet.",
                 "Don't put me to sleep. Don't sing to me. Listen to me or let me dream. But don't put me to sleep again.",
                 "Ensueña, of Those Who Hear: let it have a vote. Let it be a people, the tenth. If the nine accept it, the Root decides with us. That's why we woke it.",
                 "Níscalo, of the Mushroom: let it dream without sleeping. Neither fully awake nor asleep. The Mushroom lives on that. And the Glade eats from the Mushroom. It's the least bad.",
                 "Madreselva, of the Forest: let it sleep. With the lullaby, as always. I know what it costs: one more statue. But I know that price. I don't know the other two."],
           opts: ["“What happens if the Root votes?”", "“What happens if it dreams without sleeping?”", "“What happens if we sing it the lullaby again?”", "Accept the Root as the tenth people", "Sing it the lullaby, as always", "Let it dream awake"] },
      q1: { say: ["It votes. It decides with us, on everything that touches it. And everything touches it: every well, every sowing, every song.",
                  "And it asks for room. A new people needs land. It's the biggest of all, and it's thirsty. The other nine will have to squeeze up."] },
      q2: { say: ["It dreams without stopping, and its dream spills upward a little. Everyone will dream a little while awake. Mushrooms will grow everywhere.",
                  "And nobody will be able to tell well what's real. Not even it. Níscalo doesn't say that part."] },
      q3: { say: ["It sleeps. For a while. Someone turns to stone in the Heart, as always when someone puts it to sleep. One more statue.",
                  "And I go back to dreaming badly, alone, below. And one day someone wakes me again. You already know how it goes."] },
      voto: { say: ["The nine arrive: the Quarter with its watches, the Houses with their lanterns on the other side, the Guild with its half-cooled cracks, the Council that listened to the oaks, the summit that answered, the shadows with their mushrooms, the Tides with their jugs, the Hondura with its written wall, the Deep's watch that entered the temple.",
                    "One by one, in front of the stump, each people says the same thing: “We accept you.” The Root listens. For the first time in a thousand years, nobody sings to it and nobody promises it anything. They ask it.",
                    "A people? Me? Then I want room. I want water. I want to vote on everything. I'm big. I'm thirsty.",
                    "The nine look at each other. They already knew. That same week, in every zone, people start moving their fences to make room for the Root."] },
      nana: { say: ["Madreselva starts the lullaby, softly. Ensueña cries and doesn't sing. Níscalo doesn't either. You sing with Madreselva, and your creature too.",
                    "The Root closes its eyes, one by one, in every crack. The last thing it says, in the voice of a hundred dreamers, is: “Again.”",
                    "At dawn, in the Heart, there's a new statue. It's Madreselva, standing, mouth open on the last note. The dreamers wake and remember nothing.",
                    "It slept. As always. And someone paid. As always. This never ends, does it?"] },
      despierta: { say: ["Níscalo kneels before the stump and lays a black mushroom on the earth, the biggest of his House. The Root looks at it. Then it half closes its eyes.",
                         "It doesn't sleep. It doesn't wake. It dreams. And its dream rises through the cracks like a warm vapour, toward the Meadow, the Crater, the Heights, the Ford.",
                         "That night, all over the Glade, people walk down the street not knowing if they're asleep. Your creature looks at you oddly, as if you too were a little somewhere else.",
                         "There. Nobody will put it to sleep and nobody will fully listen to it. Mushrooms will grow everywhere. Tomorrow we'll know if that was good. Or we'll never know."] },
    } },
  });
})(window.EVEVENTS_EN);
